from lib import *
CODE, BASE = 'ck', 142
RM = lambda v: f'RM{v}'
MP_ = T('Tap one, then tap the one that is equal to it.', 'Ketik satu, kemudian ketik yang sama nilainya.')

def build():
    L = []
    def add(i, *a): L.append(level(CODE, i, BASE + i, *a))
    add(1, 'number-sense', 'fractions', 'adventurer', 'door',
        T('Cake Slices', 'Hirisan Kek'),
        T('The royal baker cuts cakes into slices. Match each fraction to the equal one!', 'Tukang roti diraja memotong kek menjadi hirisan. Padankan setiap pecahan dengan yang sama nilainya!'),
        T('Match equivalent fractions.', 'Memadankan pecahan setara.'),
        'Sprinkle', T('Sprinkle puts a cherry on every slice.', 'Sprinkle meletakkan sebiji ceri pada setiap hirisan.'),
        [match([('1/2', '2/4'), ('1/3', '3/9'), ('1/4', '2/8')], MP_, T('Multiply the top and the bottom by the same number.', 'Darabkan atas dan bawah dengan nombor yang sama.')),
         match([('2/3', '4/6'), ('3/4', '9/12'), ('1/5', '2/10'), ('3/5', '6/10')], MP_, T('Multiply the top and the bottom by the same number.', 'Darabkan atas dan bawah dengan nombor yang sama.')),
         match([('4/6', '2/3'), ('6/8', '3/4'), ('5/10', '1/2'), ('3/12', '1/4'), ('6/30', '1/5')], MP_, T('Divide the top and the bottom by the same number to make it simpler.', 'Bahagikan atas dan bawah dengan nombor yang sama untuk memudahkannya.'))])
    add(2, 'number-sense', 'fractions', 'adventurer', 'tank',
        T('Syrup Tank', 'Tangki Sirap'),
        T('Fill each syrup tank to the right line before the candy machine starts!', 'Isi setiap tangki sirap hingga garisan yang betul sebelum mesin gula-gula bermula!'),
        T('Fractions of a tank.', 'Pecahan sebuah tangki.'),
        'Syrupy', T('Syrupy is sticky from head to toe.', 'Syrupy melekit dari kepala hingga kaki.'),
        [tank(8, 3, 4), tank(12, 5, 6), tank(10, 7, 10)])
    add(3, 'operations', 'sharing', 'adventurer', 'picnic',
        T('Sweet Share', 'Kongsi Manisan'),
        T('The candy shop shares sweets between the jars. Every jar gets the same!', 'Kedai gula-gula berkongsi manisan antara balang. Setiap balang mendapat bilangan yang sama!'),
        T('Share equally using division facts.', 'Berkongsi sama banyak menggunakan fakta bahagi.'),
        'Gummy', T('Gummy bounces when he is happy.', 'Gummy melantun apabila dia gembira.'),
        [share(10, 5), share(18, 3), share(28, 4)])
    add(4, 'number-sense', 'decimals', 'adventurer', 'door',
        T('Percent Pops', 'Peratus Gula-gula'),
        T('Lollipops show their share as a percent. Match each percent to the fraction or decimal!', 'Lolipop menunjukkan bahagiannya sebagai peratus. Padankan setiap peratus dengan pecahan atau perpuluhan!'),
        T('Match percentages, fractions and decimals.', 'Memadankan peratus, pecahan dan perpuluhan.'),
        'Popsy', T('Popsy pops up wherever a sweet is open.', 'Popsy muncul di mana-mana manisan dibuka.'),
        [match([('50%', '1/2'), ('25%', '1/4'), ('10%', '1/10')], MP_, T('Percent means out of 100.', 'Peratus bermaksud daripada 100.')),
         match([('50%', '0.5'), ('25%', '0.25'), ('75%', '0.75'), ('10%', '0.1')], MP_, T('50% is 50 out of 100, which is 0.5.', '50% ialah 50 daripada 100, iaitu 0.5.')),
         match([('30%', '3/10'), ('60%', '3/5'), ('40%', '2/5'), ('90%', '9/10'), ('5%', '1/20')], MP_, T('Write each percent as a fraction out of 100, then simplify.', 'Tulis setiap peratus sebagai pecahan daripada 100, kemudian permudahkan.'))])
    add(5, 'reasoning', 'ratio', 'adventurer', 'gears',
        T('Recipe Ratios', 'Nisbah Resipi'),
        T('The royal recipe needs sugar and flour in a fixed ratio. Work out how much of each!', 'Resipi diraja memerlukan gula dan tepung dalam nisbah yang tetap. Kira berapa banyak setiap satu!'),
        T('Use ratios to scale a recipe up.', 'Menggunakan nisbah untuk menggandakan resipi.'),
        'Whisk', T('Whisk stirs the batter at top speed.', 'Whisk mengacau adunan dengan laju.'),
        [steps([step(T('A recipe uses 1 cup of sugar for every 3 cups of flour. How much flour for 4 cups of sugar?', 'Sebuah resipi menggunakan 1 cawan gula untuk setiap 3 cawan tepung. Berapa tepung untuk 4 cawan gula?'), 12, '4*3'),
                step(T('How many cups of sugar and flour altogether?', 'Berapa cawan gula dan tepung kesemuanya?'), 16, '4+12'),
                step(T('The mix is shared equally into 4 bowls. How many cups in each bowl?', 'Adunan itu dikongsi sama banyak ke dalam 4 mangkuk. Berapa cawan dalam setiap mangkuk?'), 4, '16/4')],
               T('For every 1 sugar there are 3 flour.', 'Untuk setiap 1 gula ada 3 tepung.'), T('4 × 3 = 12, then 4 + 12 = 16, then 16 ÷ 4 = 4.', '4 × 3 = 12, kemudian 4 + 12 = 16, kemudian 16 ÷ 4 = 4.'), 'ck5a'),
         steps([step(T('Red and blue sweets are in the ratio 2 to 5. There are 6 groups. How many red sweets?', 'Gula-gula merah dan biru berada dalam nisbah 2 kepada 5. Ada 6 kumpulan. Berapa gula-gula merah?'), 12, '6*2'),
                step(T('How many blue sweets?', 'Berapa gula-gula biru?'), 30, '6*5'),
                step(T('How many sweets are there in all?', 'Berapa gula-gula kesemuanya?'), 42, '12+30')],
               T('Each group has 2 red and 5 blue.', 'Setiap kumpulan ada 2 merah dan 5 biru.'), T('6 × 2 = 12, 6 × 5 = 30, then 12 + 30 = 42.', '6 × 2 = 12, 6 × 5 = 30, kemudian 12 + 30 = 42.'), 'ck5b'),
         steps([step(T('A drink uses 2 spoons of syrup for every 7 spoons of water. How much water for 8 spoons of syrup?', 'Sebuah minuman menggunakan 2 sudu sirap untuk setiap 7 sudu air. Berapa air untuk 8 sudu sirap?'), 28, '8/2*7'),
                step(T('How many spoons of drink is that in total?', 'Berapa sudu minuman itu kesemuanya?'), 36, '8+28'),
                step(T('Each cup holds 9 spoons. How many cups can be filled?', 'Setiap cawan memuatkan 9 sudu. Berapa cawan boleh diisi?'), 4, '36/9')],
               T('8 spoons is 4 groups of 2.', '8 sudu ialah 4 kumpulan 2.'), T('8 ÷ 2 × 7 = 28, then 8 + 28 = 36, then 36 ÷ 9 = 4.', '8 ÷ 2 × 7 = 28, kemudian 8 + 28 = 36, kemudian 36 ÷ 9 = 4.'), 'ck5c')])
    add(6, 'operations', 'money', 'adventurer', 'chest',
        T('Candy Coins', 'Syiling Gula-gula'),
        T('Pay for the sweets with exactly the right coins!', 'Bayar gula-gula dengan syiling yang tepat!'),
        T('Make exact amounts of money.', 'Membentuk jumlah wang yang tepat.'),
        'Cashew', T('Cashew guards the candy jar with a tiny lock.', 'Cashew menjaga balang gula-gula dengan kunci kecil.'),
        [coins(45, [5, 10, 20, 50]), coins(180, [10, 20, 50, 100]), coins(395, [5, 10, 20, 50, 100], 7)])
    add(7, 'operations', 'decimals', 'master', 'scale',
        T('Sale Day', 'Hari Jualan'),
        T('It is sale day at the candy kingdom! Work out each discount in three steps.', 'Hari jualan di kerajaan gula-gula! Kira setiap diskaun dalam tiga langkah.'),
        T('Find 10%, 25% and 50% of an amount.', 'Mencari 10%, 25% dan 50% daripada suatu jumlah.'),
        'Bargain', T('Bargain can smell a discount from far away.', 'Bargain boleh menghidu diskaun dari jauh.'),
        [steps([step(T('A giant lollipop costs RM40. What is 10% of RM40?', 'Sebiji lolipop gergasi berharga RM40. Berapakah 10% daripada RM40?'), 4, '40/10', RM),
                step(T('The discount is 10%. How much do you pay?', 'Diskaunnya 10%. Berapa yang anda bayar?'), 36, '40-4', RM),
                step(T('You pay with RM50. How much change do you get?', 'Anda membayar dengan RM50. Berapa baki yang anda terima?'), 14, '50-36', RM)],
               T('10% means divide by 10.', '10% bermaksud bahagi dengan 10.'), T('40 ÷ 10 = 4, then 40 − 4 = 36, then 50 − 36 = 14.', '40 ÷ 10 = 4, kemudian 40 − 4 = 36, kemudian 50 − 36 = 14.'), 'ck7a'),
         steps([step(T('A cake costs RM60. What is 50% of RM60?', 'Sebiji kek berharga RM60. Berapakah 50% daripada RM60?'), 30, '60/2', RM),
                step(T('Cakes are half price today. How much do 3 cakes cost?', 'Kek separuh harga hari ini. Berapa harga 3 biji kek?'), 90, '30*3', RM),
                step(T('You pay with RM100. How much change do you get?', 'Anda membayar dengan RM100. Berapa baki yang anda terima?'), 10, '100-90', RM)],
               T('50% is the same as half.', '50% sama dengan separuh.'), T('60 ÷ 2 = 30, then 30 × 3 = 90, then 100 − 90 = 10.', '60 ÷ 2 = 30, kemudian 30 × 3 = 90, kemudian 100 − 90 = 10.'), 'ck7b'),
         steps([step(T('A chocolate box costs RM80. What is 25% of RM80?', 'Sekotak coklat berharga RM80. Berapakah 25% daripada RM80?'), 20, '80/4', RM),
                step(T('The discount is 25%. How much do you pay?', 'Diskaunnya 25%. Berapa yang anda bayar?'), 60, '80-20', RM),
                step(T('Four friends share the cost equally. How much does each friend pay?', 'Empat orang kawan berkongsi kos itu sama banyak. Berapa yang dibayar oleh setiap kawan?'), 15, '60/4', RM)],
               T('25% is a quarter: divide by 4.', '25% ialah suku: bahagi dengan 4.'), T('80 ÷ 4 = 20, then 80 − 20 = 60, then 60 ÷ 4 = 15.', '80 ÷ 4 = 20, kemudian 80 − 20 = 60, kemudian 60 ÷ 4 = 15.'), 'ck7c')])
    add(8, 'number-sense', 'patterns', 'master', 'lanterns',
        T('Sweet Patterns', 'Corak Manisan'),
        T('Candy canes are arranged in growing patterns. Which number comes next?', 'Tongkat gula-gula disusun dalam pola yang bertambah. Nombor manakah yang seterusnya?'),
        T('Continue patterns that double, count up or go down.', 'Menyambung pola yang berganda, mengira ke atas atau ke bawah.'),
        'Caney', T('Caney twirls in perfect stripes.', 'Caney berpusing dalam jalur yang sempurna.'),
        [pattern('geo', 2, 3, 5, seed='ck8a'), pattern('arith', 5, 15, 5, seed='ck8b'), pattern('arith', 120, -15, 6, hidden=4, seed='ck8c')])
    add(9, 'shape-data', 'data', 'master', 'lighthouse',
        T('Candy Chart', 'Carta Gula-gula'),
        T('The candy kingdom counted the sweets sold each day. Read the chart!', 'Kerajaan gula-gula mengira manisan yang dijual setiap hari. Baca carta itu!'),
        T('Read bar charts: differences, totals and averages.', 'Membaca carta palang: beza, jumlah dan purata.'),
        'Sugary', T('Sugary sells a sweet to every passer-by.', 'Sugary menjual manisan kepada setiap orang yang lalu.'),
        [chart([(T('Mints', 'Gula-gula pudina'), 28, 'mint'), (T('Jellies', 'Jeli'), 16, 'coral'), (T('Toffees', 'Tofi'), 22, 'sun')], ('diff', 0, 1), T('sweets', 'manisan')),
         chart([(T('Mints', 'Gula-gula pudina'), 25, 'mint'), (T('Jellies', 'Jeli'), 40, 'coral'), (T('Toffees', 'Tofi'), 35, 'sun'), (T('Fudge', 'Fudj'), 15, 'grape')], ('sum', [1, 2]), T('sweets', 'manisan')),
         chart([(T('Mints', 'Gula-gula pudina'), 30, 'mint'), (T('Jellies', 'Jeli'), 45, 'coral'), (T('Toffees', 'Tofi'), 20, 'sun'), (T('Fudge', 'Fudj'), 35, 'grape'), (T('Gums', 'Gula-gula getah'), 50, 'sky')], ('mean',), T('sweets', 'manisan'))])
    add(10, 'reasoning', 'multi-step', 'master', 'windmill',
        T('Candy Castle Finale', 'Kemuncak Istana Gula-gula'),
        T('The candy castle needs one last big batch. Solve three steps to finish the royal feast!', 'Istana gula-gula memerlukan satu kelompok besar terakhir. Selesaikan tiga langkah untuk menyiapkan jamuan diraja!'),
        T('Multi-step problems with fractions, money and sharing.', 'Masalah berbilang langkah dengan pecahan, wang dan perkongsian.'),
        'Icing', T('Icing decorates the castle with a smile.', 'Icing menghias istana dengan senyuman.'),
        [steps([step(T('The baker makes 48 cupcakes. A third of them are chocolate. How many chocolate cupcakes?', 'Tukang roti membuat 48 kek cawan. Satu pertiga daripadanya ialah coklat. Berapa kek cawan coklat?'), 16, '48/3'),
                step(T('Each chocolate cupcake costs RM3. What do they cost in total?', 'Setiap kek cawan coklat berharga RM3. Berapakah jumlah harganya?'), 48, '16*3', RM),
                step(T('The baker pays with RM100. How much change does he get?', 'Tukang roti membayar dengan RM100. Berapa baki yang dia terima?'), 52, '100-48', RM)],
               T('A third means divide by 3.', 'Satu pertiga bermaksud bahagi dengan 3.'), T('48 ÷ 3 = 16, then 16 × 3 = 48, then 100 − 48 = 52.', '48 ÷ 3 = 16, kemudian 16 × 3 = 48, kemudian 100 − 48 = 52.'), 'ck10a'),
         steps([step(T('A feast has 5 trays with 24 sweets on each tray. How many sweets?', 'Sebuah jamuan mempunyai 5 dulang dengan 24 manisan pada setiap dulang. Berapa manisan?'), 120, '5*24'),
                step(T('Three quarters of the sweets are eaten. How many sweets are eaten?', 'Tiga perempat manisan dimakan. Berapa manisan yang dimakan?'), 90, '120/4*3'),
                step(T('How many sweets are left?', 'Berapa manisan yang tinggal?'), 30, '120-90')],
               T('A quarter of 120 is 30.', 'Suku daripada 120 ialah 30.'), T('5 × 24 = 120, then 120 ÷ 4 × 3 = 90, then 120 − 90 = 30.', '5 × 24 = 120, kemudian 120 ÷ 4 × 3 = 90, kemudian 120 − 90 = 30.'), 'ck10b'),
         steps([step(T('A jar holds 60 jellies. 20% are red. How many red jellies?', 'Sebuah balang memuatkan 60 jeli. 20% daripadanya merah. Berapa jeli merah?'), 12, '60/5'),
                step(T('A box holds 4 jars. How many red jellies are in the box?', 'Sebuah kotak memuatkan 4 balang. Berapa jeli merah dalam kotak itu?'), 48, '12*4'),
                step(T('The red jellies are shared equally between 6 children. How many does each child get?', 'Jeli merah itu dikongsi sama banyak antara 6 orang kanak-kanak. Berapa yang diperoleh setiap kanak-kanak?'), 8, '48/6')],
               T('20% is a fifth: divide by 5.', '20% ialah satu perlima: bahagi dengan 5.'), T('60 ÷ 5 = 12, then 12 × 4 = 48, then 48 ÷ 6 = 8.', '60 ÷ 5 = 12, kemudian 12 × 4 = 48, kemudian 48 ÷ 6 = 8.'), 'ck10c')])
    return L
